{
  "decision": "reject",
  "icd10_code": "I12.9",
  "code_display": "Hypertensive CKD",
  "guideline_citations": [
    {
      "url": "https://www.cms.gov/files/document/fy-2027-icd-10-cm-coding-guidelines.pdf",
      "quote": "Assign codes from category I12, Hypertensive chronic kidney disease, when both hypertension and a condition classifiable to category N18, Chronic kidney disease (CKD), are present. CKD should not be coded as hypertensive if the provider indicates the CKD is not related to the hypertension. The appropriate code from category N18 should be used as a secondary code with a code from category I12 to identify the stage of chronic kidney disease. See Section I.C.14. Chronic kidney disease.",
      "source": "ICD-10-CM Official Guidelines for Coding and Reporting FY 2027"
    }
  ],
  "rationale": "The chart documents CKD stage 3b (eGFR 42) and explicitly states it is 'Related to diabetic nephropathy.' This attribution to diabetic etiology indicates the CKD is not related to hypertension. Per ICD-10-CM guidelines, when the provider indicates CKD is not related to hypertension, it should not be coded as hypertensive CKD (category I12). The appropriate code would be from category N18 (or a diabetic CKD combination). No mention of hypertension is present in the provided note excerpts. Therefore, I12.9 is not supported.",
  "physician_query_needed": false
}
